[CmdletBinding()]
param()
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$keys=@('GLPI_API_BASE_URL','GLPI_API_USERNAME','GLPI_API_PASSWORD','GLPI_OAUTH_CLIENT_ID','GLPI_OAUTH_CLIENT_SECRET');$cfg=@{}
Get-Content (Join-Path $root '.env')|ForEach-Object{if($_ -match '^([^#=]+)=(.*)$' -and $keys -contains $matches[1]){$cfg[$matches[1]]=$matches[2]}}
$base=$cfg.GLPI_API_BASE_URL.TrimEnd('/');$fields=@('grant_type=password','scope=api',"username=$($cfg.GLPI_API_USERNAME)","password=$($cfg.GLPI_API_PASSWORD)","client_id=$($cfg.GLPI_OAUTH_CLIENT_ID)","client_secret=$($cfg.GLPI_OAUTH_CLIENT_SECRET)");$args=@('-sS','-w',"`n%{http_code}",'-X','POST',"$base/api.php/token",'-H','Accept: application/json','-H','Content-Type: application/x-www-form-urlencoded');foreach($field in $fields){$args+=@('--data-urlencode',$field)};$raw=(& curl.exe @args)-join "`n";$parts=$raw-split "`n(?=\d{3}$)";$token=($parts[0]|ConvertFrom-Json).access_token;if(-not $token){throw 'OAuth failed'};$headers=@{Authorization="Bearer $token";Accept='application/json'}
foreach($suffix in @('','?limit=1')){try{$result=Invoke-RestMethod -Method Get -Uri "$base/api.php/v2.3.0/Administration/Entity$suffix" -Headers $headers -ErrorAction Stop;"ENTITY_COLLECTION$($suffix) HTTP=200"}catch{$status=if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{'unknown'};$detail=if($_.ErrorDetails.Message){$_.ErrorDetails.Message}else{'none'};"ENTITY_COLLECTION$($suffix) HTTP=$status DETAIL=$detail"}}
$jsonHeaders=@{}+$headers;$jsonHeaders['Content-Type']='application/json';try{$null=Invoke-RestMethod -Method Get -Uri "$base/api.php/v2.3.0/Administration/Entity?start=0&limit=100" -Headers $jsonHeaders -ErrorAction Stop;'ENTITY_COLLECTION_WITH_JSON_CONTENT_TYPE HTTP=200'}catch{$status=if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{'unknown'};"ENTITY_COLLECTION_WITH_JSON_CONTENT_TYPE HTTP=$status"}
foreach($path in @('Dropdowns/Location','Assets/Computer','Assets/NetworkEquipment','Assistance/Ticket')){try{$null=Invoke-RestMethod -Method Get -Uri "$base/api.php/v2.3.0/$path?start=0&limit=1" -Headers $headers -ErrorAction Stop;"$path HTTP=200"}catch{$status=if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{'unknown'};"$path HTTP=$status"}}
